    "Footer-navigaatio": "Sidfotsnavigering",
    "Kirjoita sähköpostiosoitteesi": "Ange din e-postadress",
    "Sähköpostiosoitteesi": "Din e-postadress",
    "QR-koodi MID Wellbeing -testiin": "QR-kod för MID Wellbeing-testet",
    "Kieli": "Språk",
